CREATE TABLE notification(id UUID PRIMARY KEY,user_id UUID NOT NULL,type VARCHAR(64) NOT NULL,title VARCHAR(120) NOT NULL,message VARCHAR(500) NOT NULL,source_event_id UUID NOT NULL,source_aggregate_id UUID,read BOOLEAN NOT NULL DEFAULT FALSE,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_notification_source UNIQUE(user_id,type,source_event_id));CREATE INDEX idx_notification_user_created ON notification(user_id,created_at DESC);CREATE INDEX idx_notification_unread ON notification(user_id,created_at DESC) WHERE read=FALSE;
CREATE TABLE notification_preference(user_id UUID PRIMARY KEY,email_enabled BOOLEAN NOT NULL DEFAULT FALSE,sms_enabled BOOLEAN NOT NULL DEFAULT FALSE,email_address VARCHAR(254),phone_number VARCHAR(32),updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT ck_email_destination CHECK(NOT email_enabled OR email_address IS NOT NULL),CONSTRAINT ck_sms_destination CHECK(NOT sms_enabled OR phone_number IS NOT NULL));
CREATE TABLE notification_delivery(id UUID PRIMARY KEY,notification_id UUID NOT NULL REFERENCES notification(id),channel VARCHAR(16) NOT NULL,destination VARCHAR(254) NOT NULL,status VARCHAR(16) NOT NULL,attempt_count INTEGER NOT NULL DEFAULT 0,last_failure_code VARCHAR(80),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,sent_at TIMESTAMPTZ,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uq_notification_channel UNIQUE(notification_id,channel),CONSTRAINT ck_notification_channel CHECK(channel IN('EMAIL','SMS')),CONSTRAINT ck_notification_delivery_status CHECK(status IN('PENDING','PROCESSING','SENT','FAILED','SKIPPED')));CREATE INDEX idx_notification_delivery_status ON notification_delivery(status,created_at);
CREATE TABLE outbox_event(id UUID PRIMARY KEY,aggregate_type VARCHAR(64) NOT NULL,aggregate_id UUID NOT NULL,event_type VARCHAR(80) NOT NULL,event_version INTEGER NOT NULL,topic VARCHAR(255) NOT NULL,message_key VARCHAR(128) NOT NULL,payload JSONB NOT NULL,correlation_id VARCHAR(128),causation_id UUID,status VARCHAR(16) NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,available_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL,published_at TIMESTAMPTZ,last_error_code VARCHAR(200),locked_at TIMESTAMPTZ,locked_by VARCHAR(128),CONSTRAINT ck_notification_outbox_status CHECK(status IN('NEW','IN_PROGRESS','PUBLISHED','FAILED')));CREATE INDEX idx_notification_outbox_due ON outbox_event(status,available_at);
CREATE TABLE processed_event(event_id UUID NOT NULL,event_type VARCHAR(80) NOT NULL,aggregate_id UUID NOT NULL,consumer_name VARCHAR(120) NOT NULL,processed_at TIMESTAMPTZ NOT NULL,correlation_id VARCHAR(128),PRIMARY KEY(event_id,consumer_name));
